import sqlite3
import config

_conn = None

def get_conn():
    global _conn
    if _conn is None:
        _conn = sqlite3.connect(config.DB_PATH)
        _conn.executescript("""
            CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT, password TEXT, failed INTEGER DEFAULT 0);
            CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, city TEXT);
            CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, city TEXT, total REAL);
            INSERT INTO customers VALUES (1,'Asha','Delhi'),(2,'Ravi','Mumbai');
        """)
    return _conn

def find_customer(name):
    # SQL injection #1
    q = "SELECT id, name, city FROM customers WHERE name = '" + name + "'"
    return get_conn().execute(q).fetchall()

def save_order(customer_id, city, total):
    c = get_conn()
    c.execute("INSERT INTO orders (customer_id, city, total) VALUES (?,?,?)", (customer_id, city, total))
    c.commit()

def bulk_discount(subtotal):
    # Business rule 1: 10% discount on orders above 1000
    if subtotal > 1000:
        return round(subtotal * 0.10, 2)
    return 0.0

import config
import discounts

def shipping(subtotal):
    # Business rule 2: free shipping above 500, else flat 50
    return 0.0 if subtotal > 500 else 50.0

def final_price(subtotal):
    d = discounts.bulk_discount(subtotal)
    taxable = subtotal - d
    # Business rule 3: 18% GST on discounted amount
    tax = round(taxable * config.GST_RATE, 2)
    return {"subtotal": subtotal, "discount": d, "tax": tax,
            "shipping": shipping(subtotal),
            "total": round(taxable + tax + shipping(subtotal), 2)}

